python3 - <<'PY'
import re,glob,os
files=['AlgebraicJacobian/Picard/Pic0AbelianVariety.lean','AlgebraicJacobian/Picard/FGAPicRepresentability.lean','AlgebraicJacobian/Picard/IdentityComponent.lean','AlgebraicJacobian/Cohomology/CechHigherDirectImageUnconditional.lean']
# collect declaration names per file
decls={}
for f in files:
    txt=open(f).read()
    for m in re.finditer(r'^(?:@\[[^\]]*\]\s*)?(?:noncomputable\s+|private\s+|protected\s+|public\s+)*(theorem|lemma|def|instance|abbrev|structure|class)\s+([\w.\'₀-₉]+)',txt,re.M):
        decls.setdefault(m.group(2),f)
print("decls found:",len(decls))
env_re=re.compile(r'\\begin\{(theorem|lemma|proposition|corollary|definition)\}(.*?)\\end\{\1\}',re.S)
os.chdir('blueprint/src/chapters')
hits=[]
for f in sorted(glob.glob('*.tex')):
    txt=open(f).read()
    for m in env_re.finditer(txt):
        body=m.group(0); line=txt[:m.start()].count('\n')+1
        if '\\leanok' not in body: continue
        pins=[p.strip() for pp in re.findall(r'\\lean\{([^}]*)\}',body) for p in pp.split(',')]
        lbl=(re.findall(r'\\label\{([^}]*)\}',body) or ['?'])[0]
        for p in pins:
            short=p.split('.')[-1]
            for d,df in decls.items():
                if p.endswith('.'+d) or p==d or short==d:
                    hits.append((f,line,lbl,p,df)); break
for h in sorted(set(hits)):
    print(f"{h[0]}:{h[1]} {h[2]} :: {h[3]}  [{os.path.basename(h[4])}]")
print(len(set(hits)))
PY

